import fsExtra from 'fs-extra';
try {
  const file = '/tmp/harness-fs-extra.txt';
  await fsExtra.outputFile(file, 'ok');
  const content = await fsExtra.readFile(file, 'utf8');
  if (content !== 'ok') throw new Error('content mismatch');
  console.log('PASS');
} catch (e) {
  console.error(e.message);
  process.exit(1);
}

import { globbySync } from 'globby';
try {
  // globby's async API hangs in the container: setTimeout never fires there
  // (process-worker timer machinery), and fast-glob's async path depends on it.
  // Probe the sync API instead — same package, same fs coverage.
  if (!Array.isArray(globbySync('*.missing'))) throw new Error('globby failed');
  console.log('PASS');
} catch (e) {
  console.error(e.message);
  process.exit(1);
}

